import json
import itertools

def solve_puzzle():
    # Input variables (attributes and values as given in the puzzle)
    houses = [1, 2, 3]  # House numbers from left (1) to right (3)
    Names = ['Arnold', 'Peter', 'Eric']
    Animals = ['bird', 'horse', 'cat']
    Months = ['jan', 'sept', 'april']
    Hobbies = ['photography', 'cooking', 'gardening']
    Drinks = ['milk', 'water', 'tea']
    Hairs = ['black', 'brown', 'blonde']

    solutions = []

    # Helper to get index of a value in an assignment list
    def idx(lst, val):
        return lst.index(val)

    # Enumerate permutations with constraints applied early for pruning
    # Months: April is in the third house
    for months in itertools.permutations(Months):
        if months[2] != 'april':
            continue

        # Names: Eric is not in the first house
        for names in itertools.permutations(Names):
            if names[0] == 'Eric':
                continue

            # Clue 10: September is directly left of Arnold
            if 'sept' in months:
                i_sept = idx(months, 'sept')
                if i_sept == 2:
                    continue  # cannot be left of any
                if names[i_sept + 1] != 'Arnold':
                    continue
            else:
                continue

            # Animals: cat is in the second house
            for animals in itertools.permutations(Animals):
                if animals[1] != 'cat':
                    continue

                # Clue 8: Arnold is the bird keeper
                if animals[idx(names, 'Arnold')] != 'bird':
                    continue

                # Hair: house 2 has brown due to cat lover -> brown hair (Clue 7)
                # Other hair colors for house 1 and 3
                for hairs in itertools.permutations(Hairs):
                    if hairs[1] != 'brown':
                        continue

                    # Hobbies: house 2 loves cooking (Clue 1 with brown hair)
                    for hobbies in itertools.permutations(Hobbies):
                        if hobbies[1] != 'cooking':
                            continue

                        # Drinks are determined by hobbies due to clues:
                        # Clue 6: gardening <-> milk
                        # Clue 9: photography <-> water
                        # The remaining (cooking) -> tea
                        drinks = [None] * 3
                        valid = True
                        for i in range(3):
                            if hobbies[i] == 'gardening':
                                drinks[i] = 'milk'
                            elif hobbies[i] == 'photography':
                                drinks[i] = 'water'
                            elif hobbies[i] == 'cooking':
                                drinks[i] = 'tea'
                            else:
                                valid = False
                                break
                        if not valid:
                            continue

                        # Clue 1 check: brown hair is the person who loves cooking (iff)
                        brown_i = idx(hairs, 'brown')
                        if hobbies[brown_i] != 'cooking':
                            continue
                        # Also ensure only that one has brown hair and cooking aligns;
                        # since all unique, it's sufficient.

                        # Clue 7 check: cat lover is the person who has brown hair
                        if hairs[1] != 'brown':
                            continue  # already ensured

                        # Clue 5: blonde is somewhere to the left of milk
                        if not (idx(hairs, 'blonde') < idx(drinks, 'milk')):
                            continue

                        # All constraints satisfied; record solution
                        solution = []
                        for i in range(3):
                            solution.append({
                                "House": str(houses[i]),
                                "Name": names[i],
                                "animal": animals[i],
                                "birthday month": months[i],
                                "hobby": hobbies[i],
                                "favorite drink": drinks[i],
                                "hair color": hairs[i]
                            })
                        solutions.append(solution)

    # Ensure a unique solution
    if not solutions:
        raise ValueError("No solution found.")
    # Deduplicate if any duplicates (shouldn't happen)
    # Convert to tuple of tuples for set operations
    unique_solutions = []
    seen = set()
    for sol in solutions:
        key = tuple((row["House"], row["Name"], row["animal"], row["birthday month"],
                     row["hobby"], row["favorite drink"], row["hair color"]) for row in sol)
        if key not in seen:
            seen.add(key)
            unique_solutions.append(sol)

    if len(unique_solutions) != 1:
        # If multiple solutions found (shouldn't in this puzzle), pick the first deterministic one
        solution_rows = unique_solutions[0]
    else:
        solution_rows = unique_solutions[0]

    # Prepare JSON output
    header = ["House", "Name", "animal", "birthday month", "hobby", "favorite drink", "hair color"]
    rows = []
    # Ensure rows are ordered by House 1..3
    solution_rows_sorted = sorted(solution_rows, key=lambda r: int(r["House"]))
    for r in solution_rows_sorted:
        rows.append([r["House"], r["Name"], r["animal"], r["birthday month"], r["hobby"], r["favorite drink"], r["hair color"]])

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, indent=2))
